package com.motionecosystem.participantdocumentation;
import com.motionecosystem.audit.AuditRecorder; import com.motionecosystem.calendar.api.SpecialistAppointmentHistoryQueryPort; import com.motionecosystem.identityaccess.api.*; import com.motionecosystem.identityaccess.api.SpecialistAuthorizationPort; import com.motionecosystem.identityaccess.api.SpecialistAuthorizationPort.*; import com.motionecosystem.participantdocumentation.api.ParticipantDocumentationEventQueryPort; import com.motionecosystem.participantdocumentation.api.ParticipantAppointmentSummaryQueryPort;
import java.math.BigDecimal; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service
public class ParticipantDocumentationService implements ParticipantDocumentationEventQueryPort, ParticipantAppointmentSummaryQueryPort {
 private final ParticipantInterviewRepository interviews; private final InterviewResponseRepository responses; private final ParticipantNoteRepository notes; private final ParticipantDocumentationEventRepository events; private final RecordIdempotencyRepository idempotency; private final CurrentAccountService accounts; private final SpecialistAuthorizationPort authorization; private final SpecialistAppointmentHistoryQueryPort appointments; private final AuditRecorder audit; private final Clock clock;
 @Autowired ParticipantDocumentationService(ParticipantInterviewRepository i,InterviewResponseRepository r,ParticipantNoteRepository n,ParticipantDocumentationEventRepository e,RecordIdempotencyRepository d,CurrentAccountService a,SpecialistAuthorizationPort auth,SpecialistAppointmentHistoryQueryPort ap,AuditRecorder au,Clock c){interviews=i;responses=r;notes=n;events=e;idempotency=d;accounts=a;authorization=auth;appointments=ap;audit=au;clock=c;}
 ParticipantDocumentationService(ParticipantInterviewRepository i,InterviewResponseRepository r,ParticipantNoteRepository n,ParticipantDocumentationEventRepository e,RecordIdempotencyRepository d,CurrentAccountService a,SpecialistAuthorizationPort auth,AuditRecorder au,Clock c){this(i,r,n,e,d,a,auth,null,au,c);}
 @Transactional public InterviewView start(String subject,UUID participant,ActingContext ctx,String key){UUID specialist=authorize(subject,participant,ctx); String operation="INTERVIEW_START:"+participant; Optional<InterviewView> replay=replayInterview(specialist,operation,key); if(replay.isPresent()) return replay.get(); Instant now=clock.instant(); ParticipantInterview i=interviews.saveAndFlush(new ParticipantInterview(participant,specialist,now)); remember(specialist,operation,key,i.id,now); event(i.id,participant,"INTERVIEW","STARTED",now,"Interview started"); audit.record(subject,"PARTICIPANT_INTERVIEW_STARTED","ParticipantInterview",i.id);return interview(i);}
 @Transactional(readOnly=true) public List<InterviewView> list(String subject,UUID p,ActingContext c){UUID s=authorize(subject,p,c);return interviews.findByParticipantIdAndSpecialistIdOrderByCreatedAtDesc(p,s).stream().map(this::interview).toList();}
 @Transactional(readOnly=true) public InterviewView get(String subject,UUID p,UUID id,ActingContext c){return interview(ownedInterview(authorize(subject,p,c),p,id));}
 @Transactional public InterviewView save(String subject,UUID p,UUID id,ActingContext c,long expected,List<Answer> answers){ParticipantInterview i=ownedInterview(authorize(subject,p,c),p,id); version(i,expected); if(i.status!=ParticipantInterview.Status.DRAFT)throw conflict("completed interview is immutable"); responses.deleteByInterviewId(id); for(Question q:TEMPLATE) {Answer a=answers==null?null:answers.stream().filter(x->q.code().equals(x.code())).findFirst().orElse(null);if(a!=null)responses.save(new InterviewResponse(id,q,a));} i.updatedAt=clock.instant();interviews.save(i);audit.record(subject,"PARTICIPANT_INTERVIEW_DRAFT_SAVED","ParticipantInterview",id);return interview(i);}
 @Transactional public InterviewView complete(String subject,UUID p,UUID id,ActingContext c,String key,long expected){UUID s=authorize(subject,p,c); String operation="INTERVIEW_COMPLETE:"+id; Optional<InterviewView> replay=replayInterview(s,operation,key); if(replay.isPresent()) return replay.get(); ParticipantInterview i=ownedInterview(s,p,id);version(i,expected);if(i.status!=ParticipantInterview.Status.DRAFT)throw conflict("interview cannot be completed");Map<String,InterviewResponse> actual=new HashMap<>();responses.findByInterviewId(id).forEach(x->actual.put(x.code,x));for(Question q:TEMPLATE)if(q.required()&&!actual.containsKey(q.code()))throw bad("required interview question is missing: "+q.code());Instant now=clock.instant();interviews.findByParticipantIdAndSpecialistIdOrderByCreatedAtDesc(p,s).stream().filter(x->x.status==ParticipantInterview.Status.COMPLETED).forEach(x->{x.status=ParticipantInterview.Status.SUPERSEDED;x.updatedAt=now;event(x.id,p,"INTERVIEW","SUPERSEDED",now,"Interview superseded");});i.status=ParticipantInterview.Status.COMPLETED;i.completedAt=i.updatedAt=now;interviews.saveAndFlush(i);remember(s,operation,key,id,now);event(id,p,"INTERVIEW","COMPLETED",now,"Interview completed");audit.record(subject,"PARTICIPANT_INTERVIEW_COMPLETED","ParticipantInterview",id);return interview(i);}
 @Transactional(readOnly=true) public List<NoteView> notes(String subject,UUID p,ActingContext c){UUID s=authorize(subject,p,c);return notes.findByParticipantIdAndSpecialistIdOrderByUpdatedAtDesc(p,s).stream().map(this::note).toList();}
 @Transactional(readOnly=true) public NoteView note(String subject,UUID p,UUID id,ActingContext c){return note(ownedNote(authorize(subject,p,c),p,id));}
 @Override @Transactional(readOnly=true) public Optional<AppointmentSummary> findAppointmentSummary(String subject,UUID p,UUID appointmentId,ActingContext c){Optional<UUID> specialist=historySpecialist(subject,p,c);if(specialist.isEmpty())return Optional.empty();if(appointmentId==null)throw bad("appointmentId is required");return notes.findTopByParticipantIdAndSpecialistIdAndAppointmentIdAndCategoryOrderByCreatedAtDesc(p,specialist.get(),appointmentId,"APPOINTMENT_SUMMARY").map(note->new AppointmentSummary(note.id,note.title,note.content,note.createdAt));}
 @Transactional public NoteView create(String subject,UUID p,ActingContext c,String key,NoteCommand cmd){UUID s=authorize(subject,p,c);String operation="NOTE_CREATE:"+p;Optional<NoteView> replay=replayNote(s,operation,key);if(replay.isPresent())return replay.get();validate(cmd);ParticipantNote n=notes.saveAndFlush(new ParticipantNote(p,s,cmd.category().trim(),cmd.title().trim(),cmd.content().trim(),cmd.appointmentId(),clock.instant()));remember(s,operation,key,n.id,n.createdAt);event(n.id,p,"NOTE","CREATED",n.createdAt,"Note created");audit.record(subject,"PARTICIPANT_NOTE_CREATED","ParticipantNote",n.id);return note(n);}
 @Transactional public NoteView update(String subject,UUID p,UUID id,ActingContext c,long expected,NoteCommand cmd){ParticipantNote n=ownedNote(authorize(subject,p,c),p,id);version(n,expected);if(n.status!=ParticipantNote.Status.DRAFT)throw conflict("only draft notes are editable");validate(cmd);n.category=cmd.category().trim();n.title=cmd.title().trim();n.content=cmd.content().trim();n.appointmentId=cmd.appointmentId();n.updatedAt=clock.instant();notes.save(n);audit.record(subject,"PARTICIPANT_NOTE_UPDATED","ParticipantNote",id);return note(n);}
 @Transactional public NoteView finalise(String subject,UUID p,UUID id,ActingContext c,String key,long expected){UUID s=authorize(subject,p,c);String operation="NOTE_FINALISE:"+id;Optional<NoteView> replay=replayNote(s,operation,key);if(replay.isPresent())return replay.get();ParticipantNote n=ownedNote(s,p,id);version(n,expected);if(n.status!=ParticipantNote.Status.DRAFT)throw conflict("note cannot be finalised");n.status=ParticipantNote.Status.FINAL;n.finalisedAt=n.updatedAt=clock.instant();notes.saveAndFlush(n);remember(s,operation,key,id,n.updatedAt);event(id,p,"NOTE","FINALISED",n.updatedAt,"Note finalised");audit.record(subject,"PARTICIPANT_NOTE_FINALISED","ParticipantNote",id);return note(n);}
 @Transactional public NoteView archive(String subject,UUID p,UUID id,ActingContext c,String key,long expected){UUID s=authorize(subject,p,c);String operation="NOTE_ARCHIVE:"+id;Optional<NoteView> replay=replayNote(s,operation,key);if(replay.isPresent())return replay.get();ParticipantNote n=ownedNote(s,p,id);version(n,expected);if(n.status==ParticipantNote.Status.ARCHIVED)throw conflict("note already archived");n.status=ParticipantNote.Status.ARCHIVED;n.archivedAt=n.updatedAt=clock.instant();notes.saveAndFlush(n);remember(s,operation,key,id,n.updatedAt);event(id,p,"NOTE","ARCHIVED",n.updatedAt,"Note archived");audit.record(subject,"PARTICIPANT_NOTE_ARCHIVED","ParticipantNote",id);return note(n);}
 @Override @Transactional(readOnly=true) public List<Event> timeline(String subject,UUID p,ActingContext context,Instant from,Instant to){
     Optional<UUID> owner=historySpecialist(subject,p,context);
     if(owner.isEmpty())return List.of();
     return ownedEvents(p,owner.get(),events.findByParticipantIdAndEffectiveAtGreaterThanEqualAndEffectiveAtLessThanOrderByEffectiveAtDesc(p,from,to));
 }
 @Override @Transactional(readOnly=true) public Optional<Event> find(String subject,UUID p,ActingContext context,UUID id){
     Optional<UUID> owner=historySpecialist(subject,p,context);
     if(owner.isEmpty()||id==null)return Optional.empty();
     return ownedEvents(p,owner.get(),events.findByIdAndParticipantId(id,p).stream().toList()).stream().findFirst();
 }
 @Override @Transactional(readOnly=true) public Optional<DraftInterview> latestDraftInterview(String subject,UUID p,ActingContext context){
     Optional<UUID> specialistId=historySpecialist(subject,p,context);
     if(specialistId.isEmpty())return Optional.empty();
     return interviews.findFirstByParticipantIdAndSpecialistIdAndStatusOrderByUpdatedAtDescIdDesc(p,specialistId.get(),ParticipantInterview.Status.DRAFT).map(i->new DraftInterview(i.id,i.participantId,i.updatedAt));
 }
 private List<Event> ownedEvents(UUID participant,UUID specialist,List<ParticipantDocumentationEvent> source){
     Set<UUID> interviewIds=source.stream().filter(e->"INTERVIEW".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet());
     Set<UUID> noteIds=source.stream().filter(e->"NOTE".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet());
     Set<UUID> ownedInterviews=interviewIds.isEmpty()?Set.of():interviews.findByIdInAndParticipantIdAndSpecialistId(interviewIds,participant,specialist).stream().map(i->i.id).collect(java.util.stream.Collectors.toSet());
     Set<UUID> ownedNotes=noteIds.isEmpty()?Set.of():notes.findByIdInAndParticipantIdAndSpecialistId(noteIds,participant,specialist).stream().map(n->n.id).collect(java.util.stream.Collectors.toSet());
     return source.stream().filter(e->"INTERVIEW".equals(e.recordType)&&ownedInterviews.contains(e.recordId)
             ||"NOTE".equals(e.recordType)&&ownedNotes.contains(e.recordId)).map(this::eventView).toList();
 }
 private Event eventView(ParticipantDocumentationEvent e){return new Event(e.id,e.recordId,e.participantId,e.recordType,e.action,e.effectiveAt,e.recordedAt,e.neutralTitle);}
 private void event(UUID id,UUID p,String type,String action,Instant now,String title){events.save(new ParticipantDocumentationEvent(id,p,type,action,now,title));}
 @Override @Transactional(readOnly=true) public List<DocumentationHistoryCandidate> documentationCandidates(String subject,UUID p,ActingContext context,Instant from,Instant to){Optional<UUID> specialist=historySpecialist(subject,p,context);if(specialist.isEmpty())return List.of();requireRange(from,to);List<ParticipantDocumentationEvent> source=events.findByParticipantIdAndEffectiveAtGreaterThanEqualAndEffectiveAtLessThanOrderByEffectiveAtDesc(p,from,to);Map<UUID,ParticipantInterview> interviewById=interviews.findByIdInAndParticipantIdAndSpecialistId(source.stream().filter(e->"INTERVIEW".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet()),p,specialist.get()).stream().collect(java.util.stream.Collectors.toMap(i->i.id,i->i));Map<UUID,ParticipantNote> noteById=notes.findByIdInAndParticipantIdAndSpecialistId(source.stream().filter(e->"NOTE".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet()),p,specialist.get()).stream().collect(java.util.stream.Collectors.toMap(n->n.id,n->n));Set<UUID> validAppointments=validAppointmentIds(subject,p,context,noteById.values().stream().map(n->n.appointmentId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet()));return source.stream().map(e->{if("INTERVIEW".equals(e.recordType)){ParticipantInterview i=interviewById.get(e.recordId);return i==null?null:new DocumentationHistoryCandidate(e.id,i.id,"INTERVIEW",e.action,i.status.name(),null,e.effectiveAt,e.recordedAt,null);}ParticipantNote n=noteById.get(e.recordId);return n==null?null:new DocumentationHistoryCandidate(e.id,n.id,"NOTE",e.action,n.status.name(),n.category,e.effectiveAt,e.recordedAt,n.appointmentId!=null&&validAppointments.contains(n.appointmentId)?n.appointmentId:null);}).filter(Objects::nonNull).toList();}
 @Override @Transactional(readOnly=true) public List<DocumentationHistoryCandidate> documentationByEventIds(String subject,UUID p,ActingContext context,Set<UUID> eventIds){Optional<UUID> specialist=historySpecialist(subject,p,context);if(specialist.isEmpty()||eventIds==null||eventIds.isEmpty())return List.of();List<ParticipantDocumentationEvent> source=events.findByIdInAndParticipantId(eventIds,p);Map<UUID,ParticipantInterview> interviewById=interviews.findByIdInAndParticipantIdAndSpecialistId(source.stream().filter(e->"INTERVIEW".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet()),p,specialist.get()).stream().collect(java.util.stream.Collectors.toMap(i->i.id,i->i));Map<UUID,ParticipantNote> noteById=notes.findByIdInAndParticipantIdAndSpecialistId(source.stream().filter(e->"NOTE".equals(e.recordType)).map(e->e.recordId).collect(java.util.stream.Collectors.toSet()),p,specialist.get()).stream().collect(java.util.stream.Collectors.toMap(n->n.id,n->n));Set<UUID> validAppointments=validAppointmentIds(subject,p,context,noteById.values().stream().map(n->n.appointmentId).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet()));return source.stream().map(e->{if("INTERVIEW".equals(e.recordType)){ParticipantInterview i=interviewById.get(e.recordId);return i==null?null:new DocumentationHistoryCandidate(e.id,i.id,"INTERVIEW",e.action,i.status.name(),null,e.effectiveAt,e.recordedAt,null);}ParticipantNote n=noteById.get(e.recordId);return n==null?null:new DocumentationHistoryCandidate(e.id,n.id,"NOTE",e.action,n.status.name(),n.category,e.effectiveAt,e.recordedAt,n.appointmentId!=null&&validAppointments.contains(n.appointmentId)?n.appointmentId:null);}).filter(Objects::nonNull).toList();}
 @Override @Transactional(readOnly=true) public Set<UUID> appointmentIdsWithDocumentation(String subject,UUID p,ActingContext context,Set<UUID> appointmentIds){Optional<UUID> specialist=historySpecialist(subject,p,context);if(specialist.isEmpty()||appointmentIds==null||appointmentIds.isEmpty())return Set.of();Set<UUID> valid=validAppointmentIds(subject,p,context,appointmentIds);if(valid.isEmpty())return Set.of();return notes.findByParticipantIdAndSpecialistIdAndAppointmentIdIn(p,specialist.get(),valid).stream().map(n->n.appointmentId).collect(java.util.stream.Collectors.toUnmodifiableSet());}
 @Override @Transactional(readOnly=true) public List<DocumentationReference> documentationByAppointmentIds(String subject,UUID p,ActingContext context,Set<UUID> appointmentIds){Optional<UUID> specialist=historySpecialist(subject,p,context);if(specialist.isEmpty()||appointmentIds==null||appointmentIds.isEmpty())return List.of();Set<UUID> valid=validAppointmentIds(subject,p,context,appointmentIds);if(valid.isEmpty())return List.of();return notes.findByParticipantIdAndSpecialistIdAndAppointmentIdIn(p,specialist.get(),valid).stream().map(n->new DocumentationReference(n.id,n.category,n.status.name(),n.createdAt,n.updatedAt,n.appointmentId)).toList();}
 private Optional<UUID> historySpecialist(String subject,UUID p,ActingContext context){try{return Optional.of(authorize(subject,p,context));}catch(ResponseStatusException error){if(error.getStatusCode().value()==HttpStatus.FORBIDDEN.value())return Optional.empty();throw error;}}
 private Set<UUID> validAppointmentIds(String subject,UUID p,ActingContext context,Set<UUID> ids){if(appointments==null||ids.isEmpty())return Set.of();return appointments.appointmentsByIds(subject,p,context,ids).stream().filter(a->p.equals(a.participantId())).map(a->a.appointmentId()).collect(java.util.stream.Collectors.toSet());}
 private static void requireRange(Instant from,Instant to){if(from==null||to==null||!to.isAfter(from))throw bad("history range is required");}
 private UUID authorize(String subject,UUID p,ActingContext c){if(p==null)throw bad("participantId is required");var a=accounts.requireActive(subject);if(!a.hasProfile(ProfileType.SPECIALIST))throw forbidden("specialist profile is required");if(c==null||c.role()==null)throw forbidden("explicit specialist acting context is required");authorization.requireCapabilities(a.id(),p,c,Set.of(Capability.MANAGE_PARTICIPANT_RECORDS,Capability.MANAGE_PARTICIPANT_DOCUMENTATION),c.role()==ProfessionalRole.TRAINER?Purpose.PERFORMANCE_PLANNING:Purpose.FUNCTIONAL_RECOVERY);return a.id();}
 private InterviewView interview(ParticipantInterview i){List<AnswerView> a=responses.findByInterviewId(i.id).stream().map(x->new AnswerView(x.code,x.textValue,x.numberValue,x.dateValue,x.selections==null?List.of():List.of(x.selections))).toList();return new InterviewView(i.id,i.participantId,i.status,i.templateCode,i.templateVersion,TEMPLATE,a,actions(i.status),i.version,i.createdAt,i.updatedAt,i.completedAt);}
 private NoteView note(ParticipantNote n){return new NoteView(n.id,n.participantId,n.category,n.title,n.content,n.appointmentId,n.status,n.status==ParticipantNote.Status.DRAFT?List.of("UPDATE","FINALISE","ARCHIVE"):n.status==ParticipantNote.Status.FINAL?List.of("ARCHIVE"):List.of(),n.version,n.createdAt,n.updatedAt,n.finalisedAt,n.archivedAt);}
 private ParticipantInterview ownedInterview(UUID s,UUID p,UUID id){return interviews.findByIdAndParticipantIdAndSpecialistId(id,p,s).orElseThrow(()->notFound("interview"));} private ParticipantNote ownedNote(UUID s,UUID p,UUID id){return notes.findByIdAndParticipantIdAndSpecialistId(id,p,s).orElseThrow(()->notFound("note"));} private Optional<InterviewView> replayInterview(UUID s,String operation,String key){return idempotencyKey(key).flatMap(k->idempotency.findBySpecialistIdAndOperationAndKey(s,operation,k)).flatMap(x->interviews.findById(x.recordId)).map(this::interview);} private Optional<NoteView> replayNote(UUID s,String operation,String key){return idempotencyKey(key).flatMap(k->idempotency.findBySpecialistIdAndOperationAndKey(s,operation,k)).flatMap(x->notes.findById(x.recordId)).map(this::note);} private void remember(UUID s,String operation,String key,UUID id,Instant now){idempotency.saveAndFlush(new RecordIdempotency(s,operation,idempotencyKey(key).orElseThrow(),id,now));} private static Optional<String> idempotencyKey(String key){if(key==null||key.isBlank()||key.length()>120)throw bad("valid Idempotency-Key is required");return Optional.of(key.trim());} private static List<String> actions(ParticipantInterview.Status s){return s==ParticipantInterview.Status.DRAFT?List.of("SAVE_DRAFT","COMPLETE"):s==ParticipantInterview.Status.COMPLETED?List.of("START_NEXT_INTERVIEW"):List.of();} private static void version(Object o,long e){long v=o instanceof ParticipantInterview i?i.version:((ParticipantNote)o).version;if(v!=e)throw conflict("record version is stale");} private static void validate(NoteCommand n){if(n==null||blank(n.category,50)||blank(n.title,160)||blank(n.content,8000))throw bad("category, title and content are required");} private static boolean blank(String x,int n){return x==null||x.isBlank()||x.length()>n;} private static ResponseStatusException bad(String x){return new ResponseStatusException(HttpStatus.BAD_REQUEST,x);}private static ResponseStatusException forbidden(String x){return new ResponseStatusException(HttpStatus.FORBIDDEN,x);}private static ResponseStatusException conflict(String x){return new ResponseStatusException(HttpStatus.CONFLICT,x);}private static ResponseStatusException notFound(String x){return new ResponseStatusException(HttpStatus.NOT_FOUND,"participant "+x+" not found");}
 public enum AnswerType { TEXT,NUMBER,DATE,SINGLE_SELECT,MULTI_SELECT } public record Question(String code,String section,String title,AnswerType type,boolean required){} public record Answer(String code,String textValue,BigDecimal numberValue,LocalDate dateValue,List<String> selections){} public record AnswerView(String code,String textValue,BigDecimal numberValue,LocalDate dateValue,List<String> selections){} public record InterviewView(UUID id,UUID participantId,ParticipantInterview.Status status,String templateCode,int templateVersion,List<Question> questions,List<AnswerView> answers,List<String> availableActions,long version,Instant createdAt,Instant updatedAt,Instant completedAt){} public record NoteCommand(String category,String title,String content,UUID appointmentId){} public record NoteView(UUID id,UUID participantId,String category,String title,String content,UUID appointmentId,ParticipantNote.Status status,List<String> availableActions,long version,Instant createdAt,Instant updatedAt,Instant finalisedAt,Instant archivedAt){}
 static final List<Question> TEMPLATE=List.of(new Question("presenting_concern","Presenting concern","What brings the participant today?",AnswerType.TEXT,true),new Question("goals","Goals","What does the participant want to achieve?",AnswerType.TEXT,true),new Question("medical_history","Medical history","Relevant medical history",AnswerType.TEXT,false),new Question("medications","Medications","Current medications",AnswerType.TEXT,false),new Question("pain_level","Pain","Current pain level",AnswerType.NUMBER,true),new Question("injury_date","Injury history","Relevant injury date",AnswerType.DATE,false),new Question("activity_level","Activity","Current activity level",AnswerType.SINGLE_SELECT,true),new Question("sleep","Lifestyle","Sleep pattern",AnswerType.SINGLE_SELECT,false),new Question("consents","Consent","Consents discussed",AnswerType.MULTI_SELECT,true));
}
